from .intake_runtime import IntakePipelineReport, run_intake_pipeline


MAX_JSON_REQUEST_BYTES = 5_000_000
MAX_JSON_NESTING_DEPTH = 100
_INTAKE_PIPELINE_REQUIRED_FIELDS = (
    "request_id",
    "bundle_id",
    "context_key",
    "policy_id",
    "policy_version",
    "purpose",
    "permitted_uses",
    "records",
    "policy_source_id",
    "required_fields",
    "minimum_score",
    "allowed_bases",
)


def _intake_pipeline_schema() -> dict[str, Any]:
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "title": "GLIO-NONCODE intake pipeline request",
        "type": "object",
        "additionalProperties": False,
        "required": list(_INTAKE_PIPELINE_REQUIRED_FIELDS),
        "properties": {
            "request_id": {"type": "string", "minLength": 1},
            "bundle_id": {"type": "string", "minLength": 1},
            "context_key": {"type": "string", "minLength": 1},
            "policy_id": {"type": "string", "minLength": 1},
            "policy_version": {"type": "string", "minLength": 1},
            "purpose": {"type": "string", "minLength": 1},
            "permitted_uses": {"type": "array", "minItems": 1, "maxItems": 128, "items": {"type": "string", "minLength": 1}},
            "records": {"type": "array", "minItems": 1, "maxItems": 100000, "items": {"type": "object"}},
            "policy_source_id": {"type": "string", "minLength": 1},
            "source_ids": {"type": "array", "maxItems": 256, "items": {"type": "string", "minLength": 1}},
            "required_fields": {"type": "array", "minItems": 1, "maxItems": 512, "items": {"type": "string", "minLength": 1}},
            "weights": {"type": "object", "minProperties": 1, "maxProperties": 512, "additionalProperties": {"type": "number", "exclusiveMinimum": 0}},
            "minimum_score": {"type": "number", "minimum": 0, "maximum": 1},
            "allowed_bases": {"type": "string", "minLength": 1},
            "require_accepted": {"type": "boolean"},
        },
    }


def _intake_pipeline_capabilities() -> dict[str, Any]:
    return {
        "version": "intake-pipeline-v1",
        "boundary": "public_intake_pipeline",
        "method": "POST",
        "path": "/v1/intake/pipeline",
        "states": ["accepted", "review", "blocked"],
        "limits": {"max_records": 100000, "max_permitted_uses": 128, "max_sources": 256, "max_fields": 512},
        "strict_request": True,
        "public_report": True,
        "raw_records_in_report": False,
        "verification": {
            "method": "POST",
            "path": "/v1/intake/pipeline/verify",
            "schema_path": "/v1/intake/pipeline/verify/schema",
            "replays_content_address": True,
        },
    }


def _intake_pipeline_report_schema() -> dict[str, Any]:
    """Describe the path-free report accepted by the verification surface."""

    address = {"type": "string", "pattern": r"^sha256:[0-9a-f]{64}$"}
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "title": "GLIO-NONCODE intake pipeline report",
        "type": "object",
        "additionalProperties": False,
        "required": [
            "request_id",
            "bundle_id",
            "context_key",
            "state",
            "stage_receipts",
            "accepted_record_ids",
            "review_record_ids",
            "blocked_record_ids",
            "issues",
            "bundle",
            "content_address",
        ],
        "properties": {
            "request_id": {"type": "string", "minLength": 1},
            "bundle_id": {"type": "string", "minLength": 1},
            "context_key": {"type": "string", "minLength": 1},
            "state": {"enum": ["accepted", "review", "blocked"]},
            "stage_receipts": {
                "type": "array",
                "minItems": 4,
                "maxItems": 4,
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": [
                        "stage_id",
                        "capability_id",
                        "operation",
                        "state",
                        "input_count",
                        "accepted_count",
                        "review_count",
                        "issue_codes",
                        "output_address",
                        "detail",
                    ],
                    "properties": {
                        "stage_id": {"type": "string", "minLength": 1},
                        "capability_id": {"type": "string", "minLength": 1},
                        "operation": {"type": "string", "minLength": 1},
                        "state": {"enum": ["accepted", "review", "published", "blocked"]},
                        "input_count": {"type": "integer", "minimum": 0},
                        "accepted_count": {"type": "integer", "minimum": 0},
                        "review_count": {"type": "integer", "minimum": 0},
                        "issue_codes": {"type": "array", "items": {"type": "string", "minLength": 1}},
                        "output_address": address,
                        "detail": {"type": "string", "minLength": 1},
                    },
                },
            },
            "accepted_record_ids": {"type": "array", "items": {"type": "string", "minLength": 1}},
            "review_record_ids": {"type": "array", "items": {"type": "string", "minLength": 1}},
            "blocked_record_ids": {"type": "array", "items": {"type": "string", "minLength": 1}},
            "issues": {"type": "array", "items": {"type": "string", "minLength": 1}},
            "bundle": {"type": ["object", "null"]},
            "content_address": address,
            "accepted": {"type": "boolean", "readOnly": True},
            "published": {"type": "boolean", "readOnly": True},
            "stage_count": {"type": "integer", "readOnly": True},
            "accepted_count": {"type": "integer", "readOnly": True},
            "review_count": {"type": "integer", "readOnly": True},
            "blocked_count": {"type": "integer", "readOnly": True},
        },
    }


def _json_bytes(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, allow_nan=False, separators=(",", ":")).encode("utf-8")


def _strict_json_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    value: dict[str, Any] = {}
    for key, item in pairs:
        if key in value:
            raise ValueError("JSON body contains duplicate object keys")
        value[key] = item
    return value


def _strict_json_loads(value: str | bytes | bytearray, **kwargs: Any) -> Any:
    """Decode persisted or query JSON without ambiguity or non-finite numbers."""

    kwargs.setdefault("object_pairs_hook", _strict_json_object)
    kwargs.setdefault("parse_constant", _reject_non_finite_json_number)
    kwargs.setdefault("parse_float", _strict_json_float)
    return _stdlib_json_loads(value, **kwargs)


def _reject_non_finite_json_number(_value: str) -> Any:
    raise ValueError("JSON body contains a non-finite number")


def _strict_json_float(value: str) -> float:
    parsed = float(value)
    if not math.isfinite(parsed):
        raise ValueError("JSON body contains a non-finite number")
    return parsed


def _validate_json_nesting(value: str) -> None:
    """Reject pathologically deep JSON without counting brackets in strings."""

    depth = 0
    in_string = False
    escaped = False
    for character in value:
        if in_string:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == '"':
                in_string = False
            continue
        if character == '"':
            in_string = True
        elif character in "[{":
            depth += 1
            if depth > MAX_JSON_NESTING_DEPTH:
                raise ValueError(
                    "JSON request nesting exceeds "
                    f"MAX_JSON_NESTING_DEPTH ({MAX_JSON_NESTING_DEPTH})"
                )
        elif character in "]}":
            depth -= 1


def _reject_unknown_json_fields(
    value: Mapping[str, Any], allowed: set[str], label: str
) -> None:
    unknown = set(value) - allowed
    if unknown:
        raise ValueError(f"{label} contains unknown fields: {sorted(unknown)}")


def _parse_replication_pairs(query: Mapping[str, list[str]]) -> list[tuple[str, str, str]]:
    """Parse repeatable persisted packet pair references shared by release routes."""

    raw_pairs = query.get("pair", [])
    if not raw_pairs:
        raise ValueError("at least one pair=PAIR_ID=LEFT=RIGHT query value is required")
    pairs = []
    for raw_pair in raw_pairs:
        parts = raw_pair.split("=", 2)
        if len(parts) != 3 or not all(parts):
            raise ValueError("pair values must use PAIR_ID=LEFT=RIGHT")
        pairs.append((parts[0], parts[1], parts[2]))
    return pairs


def _parse_review_decisions(
    query: Mapping[str, list[str]], prefix: str = ""
) -> tuple[dict[str, Any], ...]:
    """Parse compact review decision query values without introducing identity fields."""

    raw_decisions = query.get(f"{prefix}decision", [])
    entry_ids = query.get(f"{prefix}entry_id", [])
    rationales = query.get(f"{prefix}rationale", [])
    action_values = query.get(f"{prefix}required_action", [])
    actions: dict[str, list[str]] = {}
    for raw_action in action_values:
        parts = raw_action.split("=", 1)
        if len(parts) == 2 and all(parts):
            actions.setdefault(parts[0], []).append(parts[1])
        elif raw_action:
            action_key = entry_ids[-1] if entry_ids else "review-0"
            actions.setdefault(action_key, []).append(raw_action)
    decisions: list[dict[str, Any]] = []
    for index, raw_decision in enumerate(raw_decisions):
        parts = raw_decision.split("=", 2)
        if len(parts) == 3 and all(parts):
            entry_id, decision, rationale = parts
        elif len(parts) == 2 and all(parts):
            entry_id, decision = parts
            rationale = rationales[index] if index < len(rationales) else "explicit release-window review decision"
        elif len(parts) == 1 and parts[0]:
            entry_id = entry_ids[index] if index < len(entry_ids) else f"{prefix or 'review-'}{index}"
            decision = parts[0]
            rationale = rationales[index] if index < len(rationales) else "explicit release-window review decision"
        else:
            raise ValueError("decision values must use ENTRY_ID=DECISION=RATIONALE or DECISION")
        decisions.append(
            {
                "entry_id": entry_id,
                "decision": decision,
                "rationale": rationale,
                "required_actions": tuple(actions.get(entry_id, ())),
            }
        )
    return tuple(decisions)


_API_MAX_INPUT_BYTES = 128 * 1024 * 1024


def _api_read_bytes(path: str | Path, *, field: str = "API input") -> bytes:
    """Read a bounded API file input without following symlinked paths."""

    try:
        return _safe_read_bytes_bounded(
            path,
            max_bytes=_API_MAX_INPUT_BYTES,
            field=field,
        )
    except ValidationError as exc:
        raise ValueError(str(exc)) from exc
    except OSError as exc:
        raise ValueError(f"{field} could not be read") from exc


def _api_read_text(path: str | Path, *, field: str = "API input") -> str:
    """Read a bounded UTF-8 API file input without following symlinks."""

    try:
        return _api_read_bytes(path, field=field).decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError(f"{field} is not valid UTF-8") from exc


def _module_inventory_source_signature() -> tuple[tuple[str, int, int], ...]:
    """Fingerprint source, test, and documentation inputs without exposing paths."""

    source_root = Path(__file__).resolve().parent
    test_root = source_root.parent.parent / "tests"
    docs_root = source_root.parent.parent / "docs"
    inputs = (source_root, test_root, docs_root)
    rows: list[tuple[str, int, int]] = []
    for root_index, root in enumerate(inputs):
        if not root.exists() or not root.is_dir():
            rows.append((f"root-{root_index}:missing", 0, 0))
            continue
        suffixes = ("*.py",) if root_index < 2 else ("*.md", "*.markdown")
        paths = (path for suffix in suffixes for path in root.rglob(suffix))
        for path in paths:
            if path.is_symlink() or not path.is_file():
                continue
            try:
                stat = path.stat()
            except OSError:
                continue
            relative = path.relative_to(root).as_posix()
            rows.append((f"{root_index}:{relative}", stat.st_size, stat.st_mtime_ns))
    return tuple(sorted(rows))


def _module_inventory_source_signature_map(
    signature: tuple[tuple[str, int, int], ...] | None,
) -> dict[str, tuple[int, int]]:
    """Project the source half of the service fingerprint for incremental reuse."""

    if signature is None:
        return {}
    result: dict[str, tuple[int, int]] = {}
    for row in signature:
        if not isinstance(row, tuple) or len(row) != 3:
            continue
        name, size, modified = row
        if isinstance(name, str) and name.startswith("0:"):
            result[name[2:]] = (int(size), int(modified))
    return result


_MODULE_WORKBENCH_CACHE_MAX_BYTES = 512 * 1024 * 1024
_MODULE_WORKBENCH_EXECUTION_JOURNAL_VERSION = "module-workbench-execution-journal-v1"
_MODULE_WORKBENCH_EXECUTION_JOURNAL_MAX_BYTES = 64 * 1024 * 1024
_MODULE_WORKBENCH_EXECUTION_COMMAND_FIELDS = frozenset(
    {"task_id", "action", "detail", "evidence_addresses", "requirement"}
)
_MODULE_WORKBENCH_EXECUTION_BATCH_MAX_COMMANDS = 128


class ApiHandler(BaseHTTPRequestHandler):
    """Small API handler with explicit endpoints and bounded error bodies."""

    server_version = "glio-noncode/0.1"
    runtime_factory: Callable[[], CaseRuntime] | None = None

    def _module_inventory(self, *, evidence: dict[str, Any] | None = None) -> Any:
        """Return a server-local inventory snapshot with metadata invalidation."""

        signature = _module_inventory_source_signature()
        state = getattr(self.server, "glio_module_inventory_snapshot", None)
        if state is None:
            state = {"lock": RLock(), "signature": None, "inventory": None}
            setattr(self.server, "glio_module_inventory_snapshot", state)
        with state["lock"]:
            if state["signature"] != signature or state["inventory"] is None:
                previous = state["inventory"]
                previous_signature = state["signature"]
                build_evidence = evidence if evidence is not None else {}
                state["inventory"] = build_module_inventory(
                    evidence=build_evidence,
                    previous=previous,
                    previous_source_signature=_module_inventory_source_signature_map(
                        previous_signature
                    )
                    if previous is not None
                    else None,
                    source_signature=_module_inventory_source_signature_map(signature),
                )
                state["signature"] = signature
                state["build_metadata"] = {
                    "rebuild_mode": build_evidence.get("inventory_rebuild_mode", "full"),
                    "reused_module_count": int(build_evidence.get("reused_module_count", 0)),
                    "reparsed_module_count": int(
                        build_evidence.get(
                            "reparsed_module_count",
                            len(getattr(state["inventory"], "modules", ())),
                        )
                    ),
                }
            return state["inventory"]

    def _module_workbench_cache_path(self) -> Path | None:
        value = getattr(self.server, "glio_module_workbench_cache_path", None)
        return Path(value) if value is not None else None

    def _load_module_workbench_cache_payload(self) -> Mapping[str, Any] | None:
        """Load and size-bound the durable workbench cache envelope."""

        path = self._module_workbench_cache_path()
        if path is None or not path.exists() or path.is_symlink() or not path.is_file():
            return None
        try:
            raw = _safe_read_bytes_bounded(
                path,
                max_bytes=_MODULE_WORKBENCH_CACHE_MAX_BYTES,
                field="module workbench cache",
            )
            payload = json.loads(gzip.decompress(raw).decode("utf-8"))
            return payload if isinstance(payload, Mapping) else None
        except (
            OSError,
            UnicodeDecodeError,
            ValueError,
            ValidationError,
            EOFError,
            gzip.BadGzipFile,
            zlib.error,
        ):
            return None

    @staticmethod
    def _module_workbench_cache_signature(
        payload: Mapping[str, Any],
    ) -> tuple[tuple[str, int, int], ...] | None:
        """Validate and normalize a persisted source/test signature."""

        raw_signature = payload.get("signature")
        if not isinstance(raw_signature, list):
            return None
        rows: list[tuple[str, int, int]] = []
        for row in raw_signature:
            if (
                not isinstance(row, list)
                or len(row) != 3
                or not isinstance(row[0], str)
                or isinstance(row[1], bool)
                or not isinstance(row[1], int)
                or isinstance(row[2], bool)
                or not isinstance(row[2], int)
            ):
                return None
            rows.append((row[0], row[1], row[2]))
        return tuple(rows)

    def _load_module_workbench_snapshot(
        self, signature: tuple[tuple[str, int, int], ...]
    ) -> tuple[Any, Any, Any, Any, Any] | None:
        try:
            payload = self._load_module_workbench_cache_payload()
            if payload is None:
                return None
            legacy = "payload_digest" not in payload
            snapshot = snapshot_from_mapping(
                payload,
                signature,
                verify_nested=False,
            )
            if legacy:
                self._persist_module_workbench_snapshot(signature, *snapshot)
            return snapshot
        except (
            OSError,
            UnicodeDecodeError,
            ValueError,
            ValidationError,
            EOFError,
            gzip.BadGzipFile,
            zlib.error,
        ):
            return None

    def _load_module_workbench_previous_inventory(
        self,
    ) -> tuple[Any, tuple[tuple[str, int, int], ...]] | None:
        """Hydrate only a stale inventory so unchanged source rows can be reused."""

        payload = self._load_module_workbench_cache_payload()
        if payload is None:
            return None
        try:
            stored_signature = self._module_workbench_cache_signature(payload)
            if stored_signature is None:
                return None
            snapshot = snapshot_from_mapping(
                payload,
                stored_signature,
                verify_nested=False,
            )
            return snapshot[0], stored_signature
        except (
            OSError,
            UnicodeDecodeError,
            ValueError,
            ValidationError,
            EOFError,
            gzip.BadGzipFile,
            zlib.error,
        ):
            return None

    def _persist_module_workbench_snapshot(
        self,
        signature: tuple[tuple[str, int, int], ...],
        inventory: Any,
        matrix: Any,
        lineage: Any,
        quality: Any,
        workbench: Any,
    ) -> None:
        path = self._module_workbench_cache_path()
        if path is None:
            return
        try:
            payload = snapshot_payload(signature, inventory, matrix, lineage, quality, workbench)
            encoded = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
            compressed = gzip.compress(encoded, compresslevel=6, mtime=0)
            _safe_atomic_write_bytes(path, compressed, field="module workbench cache")
        except (OSError, TypeError, ValueError, ValidationError):
            # The in-memory build remains authoritative when a local cache
            # cannot be written; a later request can rebuild it safely.
            return

    def _record_module_workbench_observation(
        self,
        signature: tuple[tuple[str, int, int], ...],
        inventory: Any,
        matrix: Any,
        lineage: Any,
        quality: Any,
        workbench: Any,
        *,
        rebuild_mode: str,
        cache_hit: bool,
        reused_module_count: int,
        reparsed_module_count: int,
    ) -> None:
        """Publish bounded build facts without retaining local filesystem paths."""

        if not all(
            hasattr(value, attribute)
            for value, attribute in (
                (inventory, "modules"),
                (matrix, "content_address"),
                (lineage, "content_address"),
                (quality, "content_address"),
                (workbench, "tasks"),
                (workbench, "content_address"),
            )
        ):
            return
        state = getattr(self.server, "glio_module_workbench_observation", None)
        if state is None:
            state = {"lock": RLock(), "value": None}
            setattr(self.server, "glio_module_workbench_observation", state)
        observation = build_module_workbench_observability(
            rebuild_mode=rebuild_mode,
            cache_hit=cache_hit,
            source_file_count=sum(item[0].startswith("0:") for item in signature),
            test_file_count=sum(item[0].startswith("1:") for item in signature),
            module_count=len(inventory.modules),
            task_count=len(workbench.tasks),
            reused_module_count=reused_module_count,
            reparsed_module_count=reparsed_module_count,
            inventory_address=inventory.content_address,
            certification_address=matrix.content_address,
            lineage_address=lineage.content_address,
            quality_address=quality.content_address,
            workbench_address=workbench.content_address,
            accepted=bool(workbench.accepted),
        )
        with state["lock"]:
            state["value"] = observation

    def _module_workbench_observation(self) -> Any:
        """Return the last bounded cache/rebuild explanation."""

        self._module_workbench_context()
        state = getattr(self.server, "glio_module_workbench_observation", None)
        if state is None:
            raise ValidationError("module workbench observability is unavailable")
        with state["lock"]:
            return state["value"]

    def _runtime(self) -> CaseRuntime:
        factory = self.runtime_factory or (lambda: CaseRuntime())
        runtime = getattr(self.server, "glio_runtime", None)
        if runtime is None:
            runtime = factory()
            setattr(self.server, "glio_runtime", runtime)  # noqa: B010 - the HTTP server is intentionally extended
        return runtime

    def _module_certification_context(
        self,
        *,
        include_certification: bool = True,
        evidence: dict[str, Any] | None = None,
    ) -> tuple[Any, Any, Any, Any, Any]:
        """Cache the immutable repository aggregate for related read routes."""

        signature = _module_inventory_source_signature()
        context = getattr(self.server, "glio_module_certification_context", None)
        context_signature = getattr(self.server, "glio_module_certification_signature", None)
        if context is None or context_signature != signature:
            inventory = self._module_inventory(evidence=evidence)
            matrix = build_module_certification(
                inventory,
                test_modules=(evidence or {}).get("test_modules"),
                source_docstring_modules=(evidence or {}).get("source_docstring_modules"),
            )
            plan = build_module_certification_task_plan(matrix) if include_certification else None
            gate = evaluate_module_certification_gate(matrix, plan) if plan is not None else None
            runtime = run_module_certification(inventory=inventory) if include_certification else None
            context = (inventory, matrix, plan, gate, runtime)
            setattr(self.server, "glio_module_certification_context", context)  # noqa: B010 - server-local cache
            setattr(self.server, "glio_module_certification_signature", signature)
        elif include_certification and context[2] is None:
            inventory, matrix, _, _, _ = context
            plan = build_module_certification_task_plan(matrix)
            gate = evaluate_module_certification_gate(matrix, plan)
            runtime = run_module_certification(inventory=inventory)
            context = (inventory, matrix, plan, gate, runtime)
            setattr(self.server, "glio_module_certification_context", context)  # noqa: B010 - server-local cache
        return context

    def _module_workbench_context(self) -> tuple[Any, Any, Any]:
        """Cache the derived lineage, quality, and workbench projections."""

        signature = _module_inventory_source_signature()
        state = getattr(self.server, "glio_module_workbench_context", None)
        if state is None:
            state = {"lock": RLock(), "signature": None, "value": None}
            setattr(self.server, "glio_module_workbench_context", state)
        with state["lock"]:
            if state["signature"] != signature or state["value"] is None:
                cached = self._load_module_workbench_snapshot(signature)
                if cached is not None:
                    inventory, matrix, lineage, quality, workbench = cached
                    certification_state = getattr(
                        self.server, "glio_module_certification_context", None
                    )
                    if certification_state is None or certification_state[0] is not inventory:
                        setattr(
                            self.server,
                            "glio_module_certification_context",
                            (inventory, matrix, None, None, None),
                        )
                        setattr(self.server, "glio_module_certification_signature", signature)
                    inventory_state = getattr(
                        self.server, "glio_module_inventory_snapshot", None
                    )
                    if inventory_state is not None:
                        with inventory_state["lock"]:
                            inventory_state["inventory"] = inventory
                            inventory_state["signature"] = signature
                            inventory_state["build_metadata"] = {
                                "rebuild_mode": "snapshot",
                                "reused_module_count": len(inventory.modules),
                                "reparsed_module_count": 0,
                            }
                    self._record_module_workbench_observation(
                        signature,
                        inventory,
                        matrix,
                        lineage,
                        quality,
                        workbench,
                        rebuild_mode="snapshot",
                        cache_hit=True,
                        reused_module_count=len(inventory.modules),
                        reparsed_module_count=0,
                    )
                else:
                    previous_inventory = self._load_module_workbench_previous_inventory()
                    if previous_inventory is not None:
                        inventory_state = getattr(
                            self.server, "glio_module_inventory_snapshot", None
                        )
                        if inventory_state is None:
                            inventory_state = {
                                "lock": RLock(),
                                "signature": None,
                                "inventory": None,
                            }
                            setattr(
                                self.server,
                                "glio_module_inventory_snapshot",
                                inventory_state,
                            )
                        with inventory_state["lock"]:
                            inventory_state["inventory"] = previous_inventory[0]
                            inventory_state["signature"] = previous_inventory[1]
                    evidence: dict[str, Any] = {}
                    inventory, matrix, _, _, _ = self._module_certification_context(
                        include_certification=False,
                        evidence=evidence,
                    )
                    lineage = build_module_certification_lineage(inventory, matrix=matrix)
                    quality = build_module_certification_quality(matrix, lineage)
                    workbench = build_module_workbench(inventory, matrix, lineage, quality)
                    self._persist_module_workbench_snapshot(
                        signature, inventory, matrix, lineage, quality, workbench
                    )
                    inventory_state = getattr(self.server, "glio_module_inventory_snapshot", None)
                    build_metadata = (
                        inventory_state.get("build_metadata", {})
                        if inventory_state is not None
                        else {}
                    )
                    self._record_module_workbench_observation(
                        signature,
                        inventory,
                        matrix,
                        lineage,
                        quality,
                        workbench,
                        rebuild_mode=str(build_metadata.get("rebuild_mode", "full")),
                        cache_hit=False,
                        reused_module_count=int(build_metadata.get("reused_module_count", 0)),
                        reparsed_module_count=int(
                            build_metadata.get(
                                "reparsed_module_count", len(getattr(inventory, "modules", ()))
                            )
                        ),
                    )
                state["value"] = (lineage, quality, workbench)
                state["signature"] = signature
            return state["value"]

    def _module_workbench_triage_context(self) -> Any:
        """Cache the ranked triage projection for every bounded queue query."""

        signature = _module_inventory_source_signature()
        state = getattr(self.server, "glio_module_workbench_triage_context", None)
        if state is None:
            state = {"lock": RLock(), "signature": None, "value": None}
            setattr(self.server, "glio_module_workbench_triage_context", state)
        with state["lock"]:
            if state["signature"] != signature or state["value"] is None:
                lineage, quality, workbench = self._module_workbench_context()
                _, matrix, _, _, _ = self._module_certification_context(
                    include_certification=False
                )
                state["value"] = build_module_workbench_triage(
                    workbench,
                    matrix,
                    lineage,
                    quality,
                )
                state["signature"] = signature
            return state["value"]

    def _module_workbench_execution_journal_path(self) -> Path | None:
        value = getattr(self.server, "glio_module_workbench_execution_journal_path", None)
        return Path(value) if value is not None else None

    @staticmethod
    def _module_workbench_execution_signature_payload(
        signature: tuple[tuple[str, int, int], ...],
    ) -> list[list[Any]]:
        return [[name, size, modified] for name, size, modified in signature]

    def _load_module_workbench_execution_journal(
        self,
        signature: tuple[tuple[str, int, int], ...],
        ledger: Any,
    ) -> tuple[Any, tuple[Any, ...]]:
        """Replay the bounded command journal only against its source snapshot."""

        path = self._module_workbench_execution_journal_path()
        if path is None or not path.exists() or path.is_symlink() or not path.is_file():
            return ledger, ()
        try:
            raw = _safe_read_bytes_bounded(
                path,
                max_bytes=_MODULE_WORKBENCH_EXECUTION_JOURNAL_MAX_BYTES,
                field="module workbench execution journal",
            )
            payload = json.loads(gzip.decompress(raw).decode("utf-8"))
            if not isinstance(payload, Mapping):
                return ledger, ()
            if payload.get("version") != _MODULE_WORKBENCH_EXECUTION_JOURNAL_VERSION:
                return ledger, ()
            source_signature_matches = (
                payload.get("source_signature")
                == self._module_workbench_execution_signature_payload(signature)
            )
            if not source_signature_matches and (
                payload.get("report_address") != ledger.report_address
                or payload.get("portfolio_address") != ledger.portfolio_address
            ):
                return ledger, ()
            raw_commands = payload.get("commands", ())
            if not isinstance(raw_commands, list) or len(raw_commands) > MODULE_WORKBENCH_EXECUTION_MAX_EVENTS:
                return ledger, ()
            current = ledger
            commands: list[Any] = []
            for raw_command in raw_commands:
                if not isinstance(raw_command, Mapping):
                    return ledger, ()
                if set(raw_command) != _MODULE_WORKBENCH_EXECUTION_COMMAND_FIELDS:
                    return ledger, ()
                raw_evidence = raw_command.get("evidence_addresses", ())
                if not isinstance(raw_evidence, list):
                    return ledger, ()
                command = execution_command(
                    raw_command.get("task_id"),
                    raw_command.get("action"),
                    raw_command.get("detail"),
                    evidence_addresses=tuple(raw_evidence),
                    requirement=raw_command.get("requirement"),
                )
                current = apply_module_workbench_execution_command(current, command)
                commands.append(command)
            if payload.get("ledger_address") != current.content_address:
                return ledger, ()
            return current, tuple(commands)
        except (
            OSError,
            UnicodeDecodeError,
            ValueError,
            TypeError,
            ValidationError,
            EOFError,
            gzip.BadGzipFile,
            zlib.error,
        ):
            return ledger, ()

    def _persist_module_workbench_execution_journal(
        self,
        signature: tuple[tuple[str, int, int], ...],
        ledger: Any,
        commands: tuple[Any, ...],
    ) -> bool:
        """Atomically persist commands after a transition has passed validation."""

        path = self._module_workbench_execution_journal_path()
        if path is None:
            return False
        try:
            payload = {
                "version": _MODULE_WORKBENCH_EXECUTION_JOURNAL_VERSION,
                "execution_version": MODULE_WORKBENCH_EXECUTION_VERSION,
                "source_signature": self._module_workbench_execution_signature_payload(signature),
                "report_address": ledger.report_address,
                "portfolio_address": ledger.portfolio_address,
                "ledger_address": ledger.content_address,
                "command_count": len(commands),
                "commands": [command.to_dict() for command in commands],
            }
            encoded = json.dumps(
                payload,
                ensure_ascii=False,
                allow_nan=False,
                separators=(",", ":"),
            ).encode("utf-8")
            compressed = gzip.compress(encoded, compresslevel=6, mtime=0)
            if len(compressed) > _MODULE_WORKBENCH_EXECUTION_JOURNAL_MAX_BYTES:
                return False
            _safe_atomic_write_bytes(path, compressed, field="module workbench execution journal")
            return True
        except (OSError, TypeError, ValueError, ValidationError):
            return False

    def _module_workbench_execution_context(self) -> dict[str, Any]:
        """Return the source-bound mutable ledger and its replayable commands."""

        signature = _module_inventory_source_signature()
        state = getattr(self.server, "glio_module_workbench_execution_context", None)
        if state is None:
            state = {"lock": RLock(), "signature": None, "ledger": None, "commands": ()}
            setattr(self.server, "glio_module_workbench_execution_context", state)
        with state["lock"]:
            if state["signature"] != signature or state["ledger"] is None:
                _lineage, _quality, workbench = self._module_workbench_context()
                portfolio = build_module_workbench_portfolio(workbench)
                base = build_module_workbench_execution(workbench, portfolio)
                ledger, commands = self._load_module_workbench_execution_journal(signature, base)
                state["ledger"] = ledger
                state["commands"] = commands
                state["signature"] = signature
            return state

    def _module_workbench_durable_execution(self) -> tuple[Any, tuple[Any, ...]]:
        """Return the current source-bound ledger and its replay commands."""

        state = self._module_workbench_execution_context()
        with state["lock"]:
            return state["ledger"], tuple(state["commands"])

    def _module_workbench_durable_packet(self, workbench: Any) -> Any:
        """Build a packet that cannot diverge from the durable execution head."""

        durable_ledger, durable_commands = self._module_workbench_durable_execution()
        trace_address = content_hash(
            [command.to_dict() for command in durable_commands],
            prefix="module-workbench-execution-command-trace",
        )
        key = (
            workbench.content_address,
            durable_ledger.content_address,
            trace_address,
        )
        cache = getattr(self.server, "glio_module_workbench_execution_projection_cache", None)
        if cache is None:
            cache = {
                "lock": RLock(),
                "packet_key": None,
                "packet": None,
                "archive_key": None,
                "archive": None,
            }
            setattr(self.server, "glio_module_workbench_execution_projection_cache", cache)
        with cache["lock"]:
            if cache["packet_key"] == key and cache["packet"] is not None:
                return cache["packet"]
            packet = build_module_workbench_execution_packet(
                workbench,
                commands=durable_commands,
            )
            if packet.ledger_address != durable_ledger.content_address:
                raise ValidationError("execution packet replay does not match the durable ledger")
            cache["packet_key"] = key
            cache["packet"] = packet
            cache["archive_key"] = None
            cache["archive"] = None
            return packet

    def _module_workbench_durable_archive(
        self,
        workbench: Any,
        *,
        archive_id: str | None = None,
    ) -> Any:
        """Reuse one immutable archive for the current packet and archive ID."""

        packet = self._module_workbench_durable_packet(workbench)
        cache = getattr(self.server, "glio_module_workbench_execution_projection_cache", None)
        if cache is None:
            raise ValidationError("execution projection cache is unavailable")
        key = (packet.content_address, archive_id)
        with cache["lock"]:
            if cache["archive_key"] == key and cache["archive"] is not None:
                return cache["archive"]
            archive = (
                build_module_workbench_execution_packet_archive(packet)
                if archive_id is None
                else build_module_workbench_execution_packet_archive(
                    packet,
                    archive_id=archive_id,
                )
            )
            cache["archive_key"] = key
            cache["archive"] = archive
            return archive

    def _deployment_guard(self) -> DeploymentGuard:
        guard = getattr(self.server, "glio_deployment_guard", None)
        if guard is None:
            guard = DeploymentGuard(default_deployment_profile("127.0.0.1"))
            setattr(self.server, "glio_deployment_guard", guard)  # noqa: B010 - server-local policy attachment
        return guard

    def _authorize_request(self) -> bool:
        """Apply the deployment profile before dispatching any API route."""

        authorization = self.headers.get("Authorization", "")
        token = authorization[7:].strip() if authorization.lower().startswith("bearer ") else None
        decision = self._deployment_guard().authorize(
            self.command,
            urlsplit(self.path).path,
            token=token,
        )
        if decision.allowed:
            return True
        status = HTTPStatus.UNAUTHORIZED if decision.reason == "missing_or_invalid_credential" else HTTPStatus.FORBIDDEN
        self._write(
            status,
            {
                "error": "authentication_required" if status is HTTPStatus.UNAUTHORIZED else "forbidden",
                "message": decision.reason,
                "operation": decision.operation.value,
                "audit_sequence": decision.audit_sequence,
            },
            headers={"WWW-Authenticate": "Bearer"} if status is HTTPStatus.UNAUTHORIZED else None,
        )
        return False

